-- Account-wide first steps; existing character definitions and reward ledgers remain intact.
CREATE TABLE objectives_account_progress (
 account_id bigint NOT NULL REFERENCES accounts(id),
 definition_key text NOT NULL REFERENCES objectives_definitions(key),
 definition_revision integer NOT NULL,
 counters jsonb NOT NULL DEFAULT '{}',
 completed_at timestamptz,
 reward_character_id bigint REFERENCES characters(id) ON DELETE SET NULL,
 updated_at timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
 PRIMARY KEY(account_id,definition_key)
);
CREATE TABLE objectives_account_sources (
 account_id bigint NOT NULL REFERENCES accounts(id),
 source_key text NOT NULL,
 event_id bigint REFERENCES objectives_events(id) ON DELETE SET NULL,
 PRIMARY KEY(account_id,source_key)
);
INSERT INTO objectives_definitions(key,definition,revision)
SELECT rule->>'key',rule,1 FROM jsonb_array_elements($onboarding$[{"description":"Enter Astrub through a world transition.","enabled":true,"key":"onboarding-v1.01","kind":"onboarding","objectives":[{"event":"map_entered","filters":{"map_id":527},"key":"arrive","target":1}],"prerequisite_keys":[],"rewards":[{"kind":"scaled","policy_key":"content-v1.daily"}],"schedule":{"timezone":"America/Bogota","type":"once"},"scope":"account","title":"Welcome to Astrub"},{"description":"Defeat three original Gobball-family monsters. Summons do not count.","enabled":true,"key":"onboarding-v1.02","kind":"onboarding","objectives":[{"event":"original_monster_killed","filters":{"references":[1,2,3,39,41,44,4085,4086]},"key":"gobballs","target":3}],"prerequisite_keys":["onboarding-v1.01"],"rewards":[{"kind":"scaled","policy_key":"content-v1.daily"}],"schedule":{"timezone":"America/Bogota","type":"once"},"scope":"account","title":"Meet the Gobballs"},{"description":"Defeat two original Tofus and one original Gobball.","enabled":true,"key":"onboarding-v1.03","kind":"onboarding","objectives":[{"event":"original_monster_killed","filters":{"references":[4,5]},"key":"tofus","target":2},{"event":"original_monster_killed","filters":{"references":[1,2,3,39,41,44,4085,4086]},"key":"gobball","target":1}],"prerequisite_keys":["onboarding-v1.02"],"rewards":[{"kind":"scaled","policy_key":"content-v1.daily"}],"schedule":{"timezone":"America/Bogota","type":"once"},"scope":"account","title":"Feathers and wool"},{"description":"Successfully plant a Gobball seed. Failed planting does not count.","enabled":true,"key":"onboarding-v1.04","kind":"onboarding","objectives":[{"event":"monster_seed_planted","filters":{"family_id":68,"resource_reference":192,"seed_reference":7361},"key":"plant","target":1}],"prerequisite_keys":["onboarding-v1.03"],"rewards":[{"kind":"scaled","policy_key":"content-v1.daily"}],"schedule":{"timezone":"America/Bogota","type":"once"},"scope":"account","title":"Give nature a hand"},{"description":"Win three completed PvE battles after unlocking this stage.","enabled":true,"key":"onboarding-v1.05","kind":"onboarding","objectives":[{"event":"combat_completed","filters":{"fight_kind":"pve","won":true},"key":"wins","target":3}],"prerequisite_keys":["onboarding-v1.04"],"rewards":[{"kind":"scaled","policy_key":"content-v1.daily"}],"schedule":{"timezone":"America/Bogota","type":"once"},"scope":"account","title":"Practice makes progress"},{"description":"Enter the Astrub Sewers through a world transition.","enabled":true,"key":"onboarding-v1.06","kind":"onboarding","objectives":[{"event":"map_entered","filters":{"map_id":546},"key":"sewers","target":1}],"prerequisite_keys":["onboarding-v1.05"],"rewards":[{"kind":"scaled","policy_key":"content-v1.daily"}],"schedule":{"timezone":"America/Bogota","type":"once"},"scope":"account","title":"Beneath Astrub"},{"description":"Complete Gobball Pastures or The Tofuhouse. Entering a dungeon is not completion.","enabled":true,"key":"onboarding-v1.07","kind":"onboarding","objectives":[{"event":"dungeon_completed","filters":{"dungeon_id":[90,27]},"key":"dungeon","target":1}],"prerequisite_keys":["onboarding-v1.06"],"rewards":[{"kind":"scaled","policy_key":"content-v1.daily"}],"schedule":{"timezone":"America/Bogota","type":"once"},"scope":"account","title":"Your first dungeon"}]$onboarding$::jsonb) rule
